import React from 'react';
import Typewriter from 'typewriter-effect';

function Type() {
  return (
    <Typewriter
      options={{
        strings: [
          'Developer',
          'Competitive Programmer',
          'MERN Stack Developer',
          'Full Stack Developer',
          'Web Developer',
          'Traveler',
        ],
        autoStart: true,
        loop: true,
        deleteSpeed: 50,
      }}
    />
  );
}

export default Type;
