import React from 'react';
import Card from 'react-bootstrap/Card';
import Button from 'react-bootstrap/Button';
import Col from 'react-bootstrap/Col';
import { BiLinkExternal } from 'react-icons/bi';
import { Link } from 'react-router-dom';

function ProjectCards(props) {
  const {
    name,
    id,
    img1,
    img2,
    img3,
    bullet1,
    bullet2,
    bullet3,
    technology,
    github,
    website,
    server,
  } = props.project;
  // console.log(props.project);
  return (
    <Col className="project-card" sm={12} md={6} lg={4}>
      <Card className="project-card-view">
        <Card.Img variant="top" src={img2} height="300px" alt="card-img" />
        <Card.Body>
          <Card.Title>{props.project.name}</Card.Title>
          <Card.Text style={{ textAlign: 'justify' }}>
            <span className="fw-bold">Project Overview:</span>
            <br />
            <ul>
              <li>{bullet1}</li>
              <li>{bullet2}</li>
              <li>{bullet3}</li>
            </ul>
            <span className="fw-bold">Technology:{technology}</span>
          </Card.Text>
        </Card.Body>
        <Card.Footer>
          <Link to={`/project/${id}`}>
            <Button variant="primary mx-1 my-1">View Details</Button>
          </Link>
          <Button variant="primary mx-1 my-1" href={website} target="_blank">
            <BiLinkExternal /> &nbsp;
            <span>View Project</span>
          </Button>
          <Button variant="primary mx-1 my-1" href={github} target="_blank">
            <BiLinkExternal /> &nbsp;
            <span>View Source</span>
          </Button>
          <Button variant="primary mx-1 my-1" href={server} target="_blank">
            <BiLinkExternal /> &nbsp;
            <span>View Server Code</span>
          </Button>
        </Card.Footer>
      </Card>
    </Col>
  );
}
export default ProjectCards;
