import axios from 'axios';
import React from 'react';
import { Button, Carousel, Container, Image } from 'react-bootstrap';
import { BiLinkExternal } from 'react-icons/bi';
import { useHistory, useParams } from 'react-router-dom';
import Particle from '../Particle';

const ProjectDetails = () => {
  const { id } = useParams();
  const [projects, setProjects] = React.useState([]);
  axios
    .get(
      'https://raw.githubusercontent.com/saifbashar/web-dev/main/project.JSON'
    )
    .then((res) => {
      setProjects(res.data);
    });
  const root = projects.filter((project) => project.id === id);
  console.log(root[0]);

  //   console.log(id);
  return (
    <Container fluid className="project-section">
      <Particle />
      <div className="mx-auto">
        <Carousel className="w-75 mx-auto ">
          <Carousel.Item interval={1000}>
            <img
              className="d-block w-100"
              src={root[0]?.img2}
              alt="First slide"
            />
            {/* <Carousel.Caption>
              <h3>{root[0]?.name}</h3>
              <p>Technology:{root[0]?.technology}</p>
            </Carousel.Caption> */}
          </Carousel.Item>
          <Carousel.Item interval={500}>
            <img
              className="d-block w-100"
              src={root[0]?.img3}
              alt="Second slide"
            />
            {/* <Carousel.Caption>
              <h3>{root[0]?.name}</h3>
              <p>Technology:{root[0]?.technology}</p>
            </Carousel.Caption> */}
          </Carousel.Item>
        </Carousel>
        <Container className="text-white mt-2">
          <h1 className="text-center fw-bold purple">{root[0]?.name}</h1>
          <div className="text-left">
            <h4 className="purple">Project Overview:</h4>
            <ul>
              <li>{root[0]?.bullet1}</li>
              <li>{root[0]?.bullet2}</li>
              <li>{root[0]?.bullet3}</li>
            </ul>
            <h4 className="purple">Technology:</h4>
            <span>{root[0]?.technology}</span>
            <br></br>
            <br></br>
            <br></br>
            <div className="text-center">
              {' '}
              <Button
                variant="primary mx-1"
                href={root[0]?.website}
                target="_blank"
                className="my-1"
              >
                <BiLinkExternal /> &nbsp;
                <span>View Project</span>
              </Button>
              <Button
                variant="primary mx-1"
                href={root[0]?.github}
                target="_blank"
                className="my-1"
              >
                <BiLinkExternal /> &nbsp;
                <span>View Source</span>
              </Button>
              <Button
                variant="primary mx-1"
                href={root[0]?.server}
                className="my-1"
                target="_blank"
              >
                <BiLinkExternal /> &nbsp;
                <span>View Server Code</span>
              </Button>
            </div>
            <br></br>
            <div className="text-center">
              <h2 className="purple">Full Site Screenshot</h2>
              <Image className="img-fluid" src={root[0]?.img1} />
            </div>
          </div>
        </Container>
      </div>
    </Container>
  );
};

export default ProjectDetails;
